// n8n Code node (JavaScript) — Run Once for All Items
// Merges upstream security inputs into a lean AI-ready payload:
//   { summary, data, attentionItems }
//
// Design goals for AI summarization:
// - Prefer structured facts over duplicated prose
// - Cap long lists (top N only)
// - Keep MFA on licensed users only
// - Offline = OS inventory timestamp > 7 days (fallback: antivirus.timestamp)

const RMM_OFFLINE_AFTER_DAYS = 14;
const MAX_OFFLINE_DEVICES = 10;
const MAX_VULNS = 5;
const MAX_INBOXES = 5;
const MAX_MFA_GAPS = 10;
const MAX_ADMINS = 15;
const MAX_MANAGED_DEVICES = 10;

function n(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function s(value) {
  if (value === null || value === undefined) return null;
  const string = String(value).trim();
  return string.length ? string : null;
}

function pct(part, total, decimals = 1) {
  if (part == null || total == null || Number(total) <= 0) return null;
  const value = (Number(part) / Number(total)) * 100;
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function collectSections() {
  const sections = [];
  const visited = new Set();

  function visit(value) {
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    if (!value || typeof value !== "object" || visited.has(value)) return;
    visited.add(value);
    sections.push(value);
    for (const key of ["inputData", "items", "summaries"]) {
      if (Array.isArray(value[key])) value[key].forEach(visit);
    }
  }

  for (const item of $input.all()) {
    visit(item?.json?.body ?? item?.json);
  }
  return sections;
}

function findSection(sections, predicate) {
  return sections.find(predicate) || {};
}

function findSections(sections, predicate) {
  return sections.filter(predicate);
}

function parseDeviceSyncTimestamp(timestamp) {
  if (timestamp == null || timestamp === "") return null;
  let ts = Number(timestamp);
  if (!Number.isFinite(ts)) return null;
  if (ts > 1e10) ts = ts / 1000;
  const lastSeen = new Date(ts * 1000);
  return Number.isNaN(lastSeen.getTime()) ? null : lastSeen;
}

function daysSinceDeviceSync(timestamp) {
  const lastSeen = parseDeviceSyncTimestamp(timestamp);
  if (!lastSeen) return null;
  return Math.floor((Date.now() - lastSeen.getTime()) / 86400000);
}

function getDeviceSyncTimestamp(device) {
  return (
    device?.operatingSystem?.timestamp ??
    device?.antivirus?.timestamp ??
    null
  );
}

function topEntries(obj, limit = 5) {
  return Object.entries(obj || {})
    .map(([key, value]) => ({ method: key, count: n(value) || 0 }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

const sections = collectSections();

const clientMeta = findSection(sections, (x) => x?.["Client Name"] != null);

const cippSummary = findSection(
  sections,
  (x) =>
    x?.summary === true &&
    (x?.tenantMaxScore != null || x?.tenantCurrentScore != null)
);

const identitySource = findSection(
  sections,
  (x) =>
    Array.isArray(x?.results) &&
    x?.totalUsers != null &&
    x.results.some((u) => u?.MFAEnabled != null || u?.assignedLicenses != null)
);

const sharePointSource = findSection(
  sections,
  (x) => x?.sharepointStorageSummary != null
);

const vulnerabilitySource = findSection(
  sections,
  (x) =>
    x?.totalUniqueVulnerabilities != null ||
    Array.isArray(x?.topVulnerabilities)
);

const emailThreatSource = findSection(
  sections,
  (x) =>
    x?.grandTotalBlocked != null ||
    x?.totalBlockedByType != null ||
    Array.isArray(x?.top5Inboxes)
);

const endpointSource = findSection(
  sections,
  (x) => x?.type === "endpoint_summary"
);

const rmmSource = findSection(
  sections,
  (x) =>
    x?.summary &&
    typeof x.summary === "object" &&
    (x.summary?.activeEndpoints != null ||
      x.summary?.offlineEndpoints != null ||
      x.summary?.inactiveEndpoints != null)
);

const managedDeviceSources = findSections(
  sections,
  (x) =>
    x?.deviceName != null &&
    (x?.complianceState != null ||
      x?.managementState != null ||
      x?.isEncrypted != null ||
      x?.storageUsedPercent != null)
);

const adminRoleSources = findSections(
  sections,
  (x) =>
    x?.adminRole != null &&
    (x?.user != null || x?.userPrincipalName != null)
);

// ---------------------------------------------------------------------------
// Report context
// ---------------------------------------------------------------------------

const reportContext = {
  clientName: s(clientMeta?.["Client Name"]),
  reportPeriod: s(clientMeta?.["Report Period"]),
  language: s(clientMeta?.Language),
};

// ---------------------------------------------------------------------------
// Secure Score
// ---------------------------------------------------------------------------

const tenantMaxScore = n(cippSummary?.tenantMaxScore);
const tenantCurrentScore = n(cippSummary?.tenantCurrentScore);
let tenantScorePercent = n(cippSummary?.tenantScorePercent);
if (
  tenantScorePercent == null &&
  tenantCurrentScore != null &&
  tenantMaxScore != null
) {
  tenantScorePercent = pct(tenantCurrentScore, tenantMaxScore, 2);
}

const microsoftTenantPosture = {
  currentScore: tenantCurrentScore,
  maximumScore: tenantMaxScore,
  scorePercent: tenantScorePercent,
  comparativeBasis: s(cippSummary?.comparativeBasis),
  comparativePercent: n(cippSummary?.comparativePercent),
};

// ---------------------------------------------------------------------------
// Identity / licensed MFA
// ---------------------------------------------------------------------------

const identityResults = Array.isArray(identitySource?.results)
  ? identitySource.results
  : [];

const totalUsers = n(identitySource?.totalUsers) ?? identityResults.length;

const licensedUsers = identityResults.filter((user) => {
  const licenses = s(user?.assignedLicenses);
  return licenses != null && licenses.toLowerCase() !== "unassigned";
});

const licensedMfaEnabled = licensedUsers.filter((u) => u?.MFAEnabled === true).length;
const licensedMfaDisabled = licensedUsers.filter((u) => u?.MFAEnabled === false).length;
const mfaCoveragePercent = pct(
  licensedMfaEnabled,
  licensedMfaEnabled + licensedMfaDisabled,
  1
);

const mfaMethodUsage = {};
for (const user of licensedUsers) {
  const methods = Array.isArray(user?.MFAMethods) ? user.MFAMethods : [];
  for (const method of new Set(methods.map(s).filter(Boolean))) {
    mfaMethodUsage[method] = (mfaMethodUsage[method] || 0) + 1;
  }
}

const licensedUsersWithoutMfa = licensedUsers
  .filter((user) => user?.MFAEnabled !== true)
  .map((user) => ({
    displayName: s(user?.displayName),
    userPrincipalName: s(user?.userPrincipalName),
  }));

const identitySecurity = {
  totalUsers,
  licensedUsers: licensedUsers.length,
  unassignedLicenseUsers: identityResults.filter(
    (u) => s(u?.assignedLicenses)?.toLowerCase() === "unassigned"
  ).length,
  unknownLicenseUsers: identityResults.filter(
    (u) => s(u?.assignedLicenses) == null
  ).length,
  mfaEnabledUsers: licensedMfaEnabled,
  mfaDisabledUsers: licensedMfaDisabled,
  mfaCoveragePercent,
  licensedUsersWithoutMfaCount: licensedUsersWithoutMfa.length,
  licensedUsersWithoutMfa: licensedUsersWithoutMfa.slice(0, MAX_MFA_GAPS),
  topMfaMethods: topEntries(mfaMethodUsage, 5),
};

// ---------------------------------------------------------------------------
// Endpoint security + RMM availability (timestamp-based offline)
// ---------------------------------------------------------------------------

const ninjaDevices = Array.isArray(endpointSource?.devicesDetailed)
  ? endpointSource.devicesDetailed
  : [];

const activeDevices = [];
const offlineDevices = [];
const inactiveDevices = [];

for (const device of ninjaDevices) {
  const timestamp = getDeviceSyncTimestamp(device);
  const days = daysSinceDeviceSync(timestamp);
  const lastSeen = parseDeviceSyncTimestamp(timestamp);
  const row = {
    computerName: s(device?.deviceName),
    deviceId: device?.deviceId ?? null,
    lastCheckin: lastSeen ? lastSeen.toISOString() : null,
    daysSinceSync: days,
  };

  if (days == null) inactiveDevices.push(row);
  else if (days > RMM_OFFLINE_AFTER_DAYS) offlineDevices.push(row);
  else activeDevices.push(row);
}

const rmmTotal =
  activeDevices.length + offlineDevices.length + inactiveDevices.length;
const rmmFallback = rmmSource?.summary || {};

const availability =
  rmmTotal > 0
    ? {
        totalEndpoints: rmmTotal,
        activeEndpoints: activeDevices.length,
        offlineEndpoints: offlineDevices.length,
        inactiveEndpoints: inactiveDevices.length,
        offlineAfterDays: RMM_OFFLINE_AFTER_DAYS,
        activePercent: pct(activeDevices.length, rmmTotal, 1),
        offlinePercent: pct(offlineDevices.length, rmmTotal, 1),
        inactivePercent: pct(inactiveDevices.length, rmmTotal, 1),
        offlineDevices: offlineDevices.slice(0, MAX_OFFLINE_DEVICES),
        inactiveDevices: inactiveDevices.slice(0, MAX_OFFLINE_DEVICES),
      }
    : {
        totalEndpoints: n(rmmFallback.totalEndpoints),
        activeEndpoints: n(rmmFallback.activeEndpoints),
        offlineEndpoints: n(rmmFallback.offlineEndpoints),
        inactiveEndpoints: n(
          rmmFallback.inactiveEndpoints ?? rmmSource?.inactiveDeviceCount
        ),
        offlineAfterDays: RMM_OFFLINE_AFTER_DAYS,
        activePercent:
          n(rmmFallback.statusPercentages?.active) ??
          pct(rmmFallback.activeEndpoints, rmmFallback.totalEndpoints, 1),
        offlinePercent:
          n(rmmFallback.statusPercentages?.offline) ??
          pct(rmmFallback.offlineEndpoints, rmmFallback.totalEndpoints, 1),
        inactivePercent:
          n(rmmFallback.statusPercentages?.inactive) ??
          pct(rmmFallback.inactiveEndpoints, rmmFallback.totalEndpoints, 1),
        offlineDevices: [],
        inactiveDevices: Array.isArray(rmmSource?.inactiveDevices)
          ? rmmSource.inactiveDevices
              .map((d) => ({
                computerName: s(d?.computerName || d?.hostname || d?.deviceName),
                lastCheckin: s(d?.lastCheckin),
                daysSinceSync: null,
              }))
              .filter((d) => d.computerName)
              .slice(0, MAX_OFFLINE_DEVICES)
          : [],
      };

const endpointTotal = n(endpointSource?.totalEndpoints);
const protectedEndpoints = n(endpointSource?.protectedEndpoints);
const unprotectedEndpoints = n(endpointSource?.unprotectedEndpoints);

const immediateActions = Array.isArray(endpointSource?.keyInsights?.immediateActions)
  ? endpointSource.keyInsights.immediateActions.map(s).filter(Boolean)
  : [];

const endpoints = {
  security: {
    totalEndpoints: endpointTotal,
    protectedEndpoints,
    unprotectedEndpoints,
    protectedPercent:
      n(endpointSource?.protectedPercentage) ??
      pct(protectedEndpoints, endpointTotal, 1),
    securityScore: n(endpointSource?.securityScore),
    securityGrade: s(endpointSource?.quickStats?.securityGrade),
    riskLevel: s(endpointSource?.quickStats?.riskLevel),
    complianceLevel: s(endpointSource?.keyInsights?.complianceLevel),
    antivirusDisabled: n(endpointSource?.antivirusDisabled),
    outdatedDefinitions: n(endpointSource?.outdatedDefinitions),
    totalMissingPatches: n(endpointSource?.totalMissingPatches),
    devicesWithMissingPatches: n(endpointSource?.devicesWithMissingPatches),
    patchCompliancePercent: n(endpointSource?.patchCompliancePercentage),
    legacySystemsCount: n(
      endpointSource?.operatingSystemSummary?.legacySystemsCount
    ),
    immediateActions,
  },
  availability,
};

// ---------------------------------------------------------------------------
// Vulnerabilities
// ---------------------------------------------------------------------------

const topVulnerabilities = (
  Array.isArray(vulnerabilitySource?.topVulnerabilities)
    ? vulnerabilitySource.topVulnerabilities
    : []
)
  .slice(0, MAX_VULNS)
  .map((v) => ({
    cveId: s(v?.cveId),
    severity: s(v?.severity),
    cvssScore: n(v?.cvssScore),
    softwareName: s(v?.softwareName),
    securityUpdateAvailable: v?.securityUpdateAvailable ?? null,
    affectedDevicesCount: n(v?.affectedDevicesCount),
  }));

const highestCvssScore =
  topVulnerabilities.reduce(
    (highest, v) => (v.cvssScore != null ? Math.max(highest, v.cvssScore) : highest),
    0
  ) || null;

const vulnerabilityExposure = {
  assessedDevices: n(vulnerabilitySource?.totalDevices),
  totalUniqueVulnerabilities: n(vulnerabilitySource?.totalUniqueVulnerabilities),
  highestCvssScore,
  criticalTopVulnerabilityCount: topVulnerabilities.filter(
    (v) => v.severity?.toLowerCase() === "critical"
  ).length,
  topVulnerabilities,
};

// ---------------------------------------------------------------------------
// Email threats
// ---------------------------------------------------------------------------

const totalBlockedByType =
  emailThreatSource?.totalBlockedByType &&
  typeof emailThreatSource.totalBlockedByType === "object"
    ? emailThreatSource.totalBlockedByType
    : {};

const calculatedBlockedTotal = Object.values(totalBlockedByType).reduce(
  (total, value) => total + (n(value) || 0),
  0
);

const topInboxes = (
  Array.isArray(emailThreatSource?.top5Inboxes)
    ? emailThreatSource.top5Inboxes
    : []
)
  .slice(0, MAX_INBOXES)
  .map((inbox) => ({
    email: s(inbox?.email),
    totalBlocked: n(inbox?.totalBlocked),
  }));

const emailThreatProtection = {
  grandTotalBlocked:
    n(emailThreatSource?.grandTotalBlocked) ?? calculatedBlockedTotal,
  totalBlockedByType,
  topInboxes,
};

// ---------------------------------------------------------------------------
// Managed devices + privileged access + storage
// ---------------------------------------------------------------------------

const managedDevices = managedDeviceSources.map((device) => ({
  deviceName: s(device?.deviceName),
  complianceState: s(device?.complianceState),
  isEncrypted:
    typeof device?.isEncrypted === "boolean" ? device.isEncrypted : null,
  joinType: s(device?.joinType),
  storageUsedPercent: n(device?.storageUsedPercent),
}));

const managedDevicePosture = {
  totalDevices: managedDevices.length,
  compliantDevices: managedDevices.filter(
    (d) => d.complianceState?.toLowerCase() === "compliant"
  ).length,
  encryptedDevices: managedDevices.filter((d) => d.isEncrypted === true).length,
  sampleDevices: managedDevices.slice(0, MAX_MANAGED_DEVICES),
};

const privilegedAccounts = adminRoleSources
  .map((account) => ({
    user: s(account?.user),
    userPrincipalName: s(account?.userPrincipalName),
    adminRole: s(account?.adminRole),
  }))
  .slice(0, MAX_ADMINS);

const privilegedAccess = {
  adminRoleAssignmentCount: adminRoleSources.length,
  accounts: privilegedAccounts,
};

const cloudStorage = {
  sharePointStorageSummary: s(sharePointSource?.sharepointStorageSummary),
};

// ---------------------------------------------------------------------------
// Attention items for the AI (what to emphasize)
// ---------------------------------------------------------------------------

const attentionItems = [];

function pushAttention(severity, area, message) {
  attentionItems.push({ severity, area, message });
}

if (mfaCoveragePercent != null && mfaCoveragePercent < 100) {
  pushAttention(
    mfaCoveragePercent < 80 ? "high" : "medium",
    "identity",
    `Licensed MFA coverage is ${mfaCoveragePercent}% (${licensedMfaDisabled} licensed users without MFA).`
  );
}

if ((endpoints.security.unprotectedEndpoints || 0) > 0) {
  pushAttention(
    "high",
    "endpoints",
    `${endpoints.security.unprotectedEndpoints} endpoints are unprotected.`
  );
}

if ((endpoints.security.totalMissingPatches || 0) > 0) {
  pushAttention(
    "medium",
    "patching",
    `${endpoints.security.totalMissingPatches} missing patches across ${endpoints.security.devicesWithMissingPatches ?? "?"} devices.`
  );
}

if ((endpoints.security.legacySystemsCount || 0) > 0) {
  pushAttention(
    "medium",
    "endpoints",
    `${endpoints.security.legacySystemsCount} legacy operating systems detected.`
  );
}

if ((availability.offlineEndpoints || 0) > 0) {
  pushAttention(
    availability.offlinePercent >= 40 ? "high" : "medium",
    "availability",
    `${availability.offlineEndpoints} endpoints offline (>${RMM_OFFLINE_AFTER_DAYS}d since OS sync).`
  );
}

if ((vulnerabilityExposure.totalUniqueVulnerabilities || 0) > 0) {
  pushAttention(
    (highestCvssScore || 0) >= 9 ? "high" : "medium",
    "vulnerabilities",
    `${vulnerabilityExposure.totalUniqueVulnerabilities} unique vulnerabilities; highest CVSS ${highestCvssScore ?? "unknown"}.`
  );
}

if (
  tenantScorePercent != null &&
  microsoftTenantPosture.comparativePercent != null &&
  tenantScorePercent < microsoftTenantPosture.comparativePercent
) {
  pushAttention(
    "medium",
    "secureScore",
    `Tenant Secure Score (${tenantScorePercent}%) is below peer comparative (${microsoftTenantPosture.comparativePercent}%).`
  );
}

if (immediateActions.length) {
  pushAttention("medium", "actions", immediateActions.join(" | "));
}

// Severity sort: high → medium → low
const severityRank = { high: 0, medium: 1, low: 2 };
attentionItems.sort(
  (a, b) => (severityRank[a.severity] ?? 9) - (severityRank[b.severity] ?? 9)
);

// ---------------------------------------------------------------------------
// Compact summary string (single source of truth for narrative input)
// ---------------------------------------------------------------------------

const lines = [];

if (reportContext.clientName || reportContext.reportPeriod) {
  lines.push(
    `Client: ${reportContext.clientName || "unknown"} | Period: ${reportContext.reportPeriod || "unknown"}`
  );
}

if (tenantScorePercent != null) {
  lines.push(
    `Secure Score: ${tenantCurrentScore}/${tenantMaxScore} (${tenantScorePercent}%), peer comparative ${microsoftTenantPosture.comparativePercent ?? "n/a"}%`
  );
}

if (totalUsers > 0) {
  lines.push(
    `Identity: ${licensedUsers.length}/${totalUsers} licensed; MFA coverage ${mfaCoveragePercent ?? "n/a"}% on licensed users; ${licensedUsersWithoutMfa.length} licensed without MFA`
  );
}

if (endpointTotal != null) {
  lines.push(
    `Endpoint security: ${protectedEndpoints}/${endpointTotal} protected (${endpoints.security.protectedPercent ?? "n/a"}%), grade ${endpoints.security.securityGrade || "n/a"}, risk ${endpoints.security.riskLevel || "n/a"}, missing patches ${endpoints.security.totalMissingPatches ?? 0}`
  );
}

if (availability.totalEndpoints != null) {
  lines.push(
    `Endpoint availability: ${availability.activeEndpoints} active / ${availability.offlineEndpoints} offline / ${availability.inactiveEndpoints} inactive of ${availability.totalEndpoints} (offline => OS sync >${RMM_OFFLINE_AFTER_DAYS}d)`
  );
}

if (vulnerabilityExposure.totalUniqueVulnerabilities != null) {
  lines.push(
    `Vulnerabilities: ${vulnerabilityExposure.totalUniqueVulnerabilities} unique across ${vulnerabilityExposure.assessedDevices ?? "n/a"} devices; highest CVSS ${highestCvssScore ?? "n/a"}`
  );
}

if (emailThreatProtection.grandTotalBlocked != null) {
  const blockedTypes = Object.entries(totalBlockedByType)
    .map(([type, total]) => `${type}=${total}`)
    .join(", ");
  lines.push(
    `Email threats blocked: ${emailThreatProtection.grandTotalBlocked}${blockedTypes ? ` (${blockedTypes})` : ""}`
  );
}

if (managedDevicePosture.totalDevices > 0) {
  lines.push(
    `Managed devices: ${managedDevicePosture.compliantDevices}/${managedDevicePosture.totalDevices} compliant, ${managedDevicePosture.encryptedDevices} encrypted`
  );
}

if (privilegedAccess.adminRoleAssignmentCount > 0) {
  lines.push(
    `Privileged access: ${privilegedAccess.adminRoleAssignmentCount} admin role assignments`
  );
}

if (cloudStorage.sharePointStorageSummary) {
  lines.push(`SharePoint storage: ${cloudStorage.sharePointStorageSummary}`);
}

if (attentionItems.length) {
  lines.push(
    `Priority findings: ${attentionItems
      .slice(0, 5)
      .map((item) => `[${item.severity}] ${item.message}`)
      .join(" || ")}`
  );
}

if (!lines.length) {
  lines.push("No relevant security inputs found.");
}

const data = {
  reportContext,
  microsoftTenantPosture,
  identitySecurity,
  endpoints,
  vulnerabilityExposure,
  emailThreatProtection,
  managedDevicePosture,
  privilegedAccess,
  cloudStorage,
};

return [
  {
    json: {
      summary: lines.join("\n"),
      attentionItems,
      data,
    },
  },
];

// Function node
const all = items.map(i => i.json);
return [{ json: { data: all } }];

// Map names to actual emails
const emailMapping = {
  "Account Manager A": "am-a@example.com",
  "Account Manager B": "am-b@example.com",
};

function isEmail(str) {
  return typeof str === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(str);
}

return items.map(item => {
  const raw = (item.json["Email Address"] ?? item.json["Send Email to"] ?? "").toString().trim();
  const emailAddress = isEmail(raw) ? raw : (emailMapping[raw] || null);
  const language = (item.json["Language"] ?? "").toString().trim();

  return {
    json: {
      emailAddress: emailAddress || "Email not found",
      language: language || "Language not found",
    }
  };
});

// n8n Code node (JavaScript)
// Fans out the incoming form submission into one item per ENABLED client.
//
// Per-client options:
//   name:      (required) client name as it should appear on the report
//   enabled:   true to include in this run, true/omitted to skip
//   language:  "French" | "English"   (default: French)
//   salesGoal: string                  (default: "")
//   email:     string                  (default: form submission's Email Address)
//
// Quick ways to skip a client:
//   - set enabled: true (or just remove the flag)
//   - comment out the whole line with //

const DEFAULTS = {
  language: "French",
  salesGoal: "",
  enabled: true,
};

const CLIENTS = [
  // Replace with your client list. Names must match the lookup maps in each section subworkflow.
  { name: "Contoso Ltd",        enabled: true, language: "English", email: "", salesGoal: "" },
  { name: "Fabrikam Inc",       enabled: true, language: "English", email: "", salesGoal: "" },
  { name: "Northwind Traders",  enabled: true, language: "French",  email: "", salesGoal: "" },
];

const submission = $input.first().json;

const todayISO = new Date().toISOString().slice(0, 10);

return CLIENTS
  .map((client) => ({
    ...client,
    name: String(client.name ?? "").trim(),
  }))
  .filter((client) => client.name && (client.enabled ?? DEFAULTS.enabled))
  .map((client) => ({
    json: {
      "Client Name": client.name,
      "Sales Goal": client.salesGoal ?? DEFAULTS.salesGoal,
      "Report Period": todayISO,
      "Email Address": client.email ?? submission["Email Address"] ?? "",
      "Language": client.language ?? DEFAULTS.language,
      submittedAt: submission.submittedAt ?? new Date().toISOString(),
      formMode: submission.formMode ?? "production",
    },
  }));

// Collect all input items into a single array
const allItems = $input.all().map(item => item.json);

return [
  {
    json: {
      summaries: allItems
    }
  }
];

// Utility: mask the 3 middle-most characters of an email's local part
function maskEmail(email) {
  if (!email || typeof email !== 'string' || !email.includes('@')) return email;

  const [local, ...domainParts] = email.split('@');
  const domain = domainParts.join('@'); // handles edge case of multiple @

  const len = local.length;

  // Need at least 3 characters to mask
  if (len < 3) return email;

  // Find the start index of the 3 middle characters
  const start = Math.floor((len - 3) / 2);
  const masked = local.slice(0, start) + '***' + local.slice(start + 3);

  return `${masked}@${domain}`;
}

// Recursively walk any object/array and mask email values
function maskEmailsInValue(value) {
  if (value === null || value === undefined) return value;

  if (typeof value === 'string') {
    // Only transform if it looks like an email
    return value.includes('@') ? maskEmail(value) : value;
  }

  if (Array.isArray(value)) {
    return value.map(maskEmailsInValue);
  }

  if (typeof value === 'object') {
    const result = {};
    for (const [key, val] of Object.entries(value)) {
      result[key] = maskEmailsInValue(val);
    }
    return result;
  }

  // Numbers, booleans, etc. — pass through untouched
  return value;
}

// Process all incoming items
return $input.all().map(item => {
  return {
    json: maskEmailsInValue(item.json)
  };
});

// n8n Code node (JavaScript)
// Fans out the incoming form submission into one item per ENABLED client.
//
// Per-client options:
//   name:      (required) client name as it should appear on the report
//   enabled:   true to include in this run, true/omitted to skip
//   language:  "French" | "English"   (default: French)
//   salesGoal: string                  (default: "")
//   email:     string                  (default: form submission's Email Address)
//
// Quick ways to skip a client:
//   - set enabled: true (or just remove the flag)
//   - comment out the whole line with //

const DEFAULTS = {
  language: "English",
  salesGoal: "",
  enabled: true,
};

const CLIENTS = [
  // Replace with your client list. Names must match the lookup maps in each section subworkflow.
  { name: "Contoso Ltd",        enabled: true, language: "English", email: "", salesGoal: "" },
  { name: "Fabrikam Inc",       enabled: true, language: "English", email: "", salesGoal: "" },
  { name: "Northwind Traders",  enabled: true, language: "French",  email: "", salesGoal: "" },
];

const submission = $input.first().json;

const todayISO = new Date().toISOString().slice(0, 10);

return CLIENTS
  .map((client) => ({
    ...client,
    name: String(client.name ?? "").trim(),
  }))
  .filter((client) => client.name && (client.enabled ?? DEFAULTS.enabled))
  .map((client) => ({
    json: {
      "Client Name": client.name,
      "Sales Goal": client.salesGoal ?? DEFAULTS.salesGoal,
      "Report Period": todayISO,
      "Email Address": client.email ?? submission["Email Address"] ?? "",
      "Language": client.language ?? DEFAULTS.language,
      submittedAt: submission.submittedAt ?? new Date().toISOString(),
      formMode: submission.formMode ?? "production",
    },
  }));
